-- Additive role catalog and explicit role grants. Existing memberships remain the tenant anchor.
-- No existing account or permission is changed by this migration.
CREATE TABLE organization_role_definitions(role TEXT PRIMARY KEY,label TEXT NOT NULL,capabilities_json TEXT NOT NULL CHECK(json_valid(capabilities_json)),assignable INTEGER NOT NULL CHECK(assignable IN(0,1)));
INSERT INTO organization_role_definitions(role,label,capabilities_json,assignable) VALUES('owner','Administrador principal','["*"]',0);
