CREATE TABLE organization_membership_settings(user_id TEXT NOT NULL,operator_id TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0),updated_by TEXT NOT NULL REFERENCES users(id),updated_at INTEGER NOT NULL,PRIMARY KEY(user_id,operator_id),FOREIGN KEY(user_id,operator_id) REFERENCES memberships(user_id,operator_id) ON DELETE CASCADE);
CREATE TABLE organization_member_roles(user_id TEXT NOT NULL,operator_id TEXT NOT NULL,role TEXT NOT NULL REFERENCES organization_role_definitions(role),PRIMARY KEY(user_id,operator_id,role),FOREIGN KEY(user_id,operator_id) REFERENCES organization_membership_settings(user_id,operator_id) ON DELETE CASCADE);
CREATE TABLE organization_vehicle_access_grants(user_id TEXT NOT NULL,operator_id TEXT NOT NULL,vehicle_id TEXT NOT NULL REFERENCES vehicles(id),PRIMARY KEY(user_id,operator_id,vehicle_id),FOREIGN KEY(user_id,operator_id) REFERENCES organization_membership_settings(user_id,operator_id) ON DELETE CASCADE);
CREATE VIEW organization_effective_roles AS SELECT m.user_id,m.operator_id,m.role FROM memberships m JOIN users u ON u.id=m.user_id AND u.status='active' WHERE m.role='owner' OR NOT EXISTS(SELECT 1 FROM organization_membership_settings s WHERE s.user_id=m.user_id AND s.operator_id=m.operator_id) UNION SELECT r.user_id,r.operator_id,r.role FROM organization_member_roles r JOIN memberships m ON m.user_id=r.user_id AND m.operator_id=r.operator_id JOIN users u ON u.id=m.user_id AND u.status='active';
CREATE VIEW organization_capabilities AS SELECT DISTINCT e.user_id,e.operator_id,j.value AS capability FROM organization_effective_roles e JOIN organization_role_definitions d ON d.role=e.role JOIN json_each(d.capabilities_json) j;
CREATE TRIGGER organization_vehicle_access_scope BEFORE INSERT ON organization_vehicle_access_grants WHEN NOT EXISTS(SELECT 1 FROM vehicles WHERE id=NEW.vehicle_id AND operator_id=NEW.operator_id) BEGIN SELECT RAISE(ABORT,'organization_resource_scope'); END;
CREATE TRIGGER organization_vehicle_access_update_scope BEFORE UPDATE ON organization_vehicle_access_grants WHEN NOT EXISTS(SELECT 1 FROM vehicles WHERE id=NEW.vehicle_id AND operator_id=NEW.operator_id) BEGIN SELECT RAISE(ABORT,'organization_resource_scope'); END;
INSERT OR IGNORE INTO schema_migrations(version) VALUES('0038_organization_roles');
